using Didww.Api3.Internal;
using Newtonsoft.Json;

namespace Didww.Api3.Resource.Configuration.SmsTrunkConfiguration;

/// <summary>
/// The customer binds to DIDWW as an SMPP ESME. <see cref="SystemId"/> and
/// <see cref="Password"/> are generated by DIDWW and are never sent in a
/// request. <see cref="ServerLocation"/> is required when the trunk is
/// created. (API 2026-10-22)
/// </summary>
public class SmppEsmeConfiguration : SmsTrunkConfigurationBase
{
    [JsonIgnore]
    public override string ConfigurationType => "smpp_esme";

    /// <summary>SMPP system_type, up to 12 characters.</summary>
    [JsonProperty("system_type")]
    public string? SystemType { get; set; }

    /// <summary>Addresses the ESME may bind from.</summary>
    [JsonProperty("allowed_ips")]
    public List<string>? AllowedIps { get; set; }

    /// <summary>Location of the DIDWW SMPP server, see <see cref="SmppServerLocations"/>.</summary>
    [JsonProperty("server_location")]
    public string? ServerLocation { get; set; }

    /// <summary>Generated SMPP system_id. Read-only: never sent in a request.</summary>
    [JsonProperty("system_id")]
    public string? SystemId { get; set; }

    /// <summary>Generated SMPP bind password. Read-only: never sent in a request.</summary>
    [JsonProperty("password")]
    public string? Password { get; set; }

    // The default ToString redacts the generated credentials. The wire
    // payload is unaffected (the converter strips them from requests).
    public override string ToString()
    {
        var ips = AllowedIps == null ? "null" : $"[{string.Join(", ", AllowedIps)}]";
        return $"SmppEsmeConfiguration(SystemType={SystemType ?? "null"}, AllowedIps={ips}, ServerLocation={ServerLocation ?? "null"}, " +
               $"SystemId={Redact.Mask(SystemId)}, Password={Redact.Mask(Password)})";
    }
}
